t-size:clamp(32px,4vw,52px);line-height:1.06}.hero p{position:relative;z-index:1;max-width:900px;color:#687487;font-size:14px;line-height:1.75;margin:0}.open{position:relative;z-index:1;display:inline-flex;gap:7px;align-items:center;margin-top:17px;padding:11px 15px;background:#635bff;color:#fff;border-radius:11px;text-decoration:none;font-size:12px;font-weight:900}.flow{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin:14px 0}.flowbox{background:#fff;border:1px solid #e1e6ef;border-radius:15px;padding:13px;text-align:center}.flowbox i{font-size:17px;color:#635bff}.flowbox b{display:block;margin-top:7px;font-size:11px}.flowbox span{display:block;color:#7a8494;font-size:10px;margin-top:3px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.card{padding:21px;margin-top:14px}.card h2{display:flex;align-items:center;gap:8px;margin:0 0 10px;font-size:19px}.card h2 i{color:#635bff}.card p,.card li{color:#5e6a7c;font-size:13px;line-height:1.75}.input{background:#f7f8fb;border:1px dashed #d7dce6;border-radius:12px;padding:14px;color:#586477;font-size:12px;line-height:1.65}.steps .step{display:grid;grid-template-columns:40px 1fr;gap:12px;padding:15px 0;border-top:1px solid #edf0f4}.num{width:34px;height:34px;border-radius:11px;background:#eeedff;color:#635bff;display:grid;place-items:center;font-weight:900}.step h3{margin:0 0 5px;font-size:14px}.step p{margin:0;color:#5f6b7d;font-size:12.5px;line-height:1.7}.tips{background:#f1f5ff}.mistakes .row{padding:10px 0;border-bottom:1px solid #edf0f4;color:#5f6b7d;font-size:12.5px}.result{background:#172033;color:#fff}.result p{color:#c0c8d6}.relatedgrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.relatedgrid a{display:flex;gap:8px;align-items:center;border:1px solid #e1e6ef;border-radius:12px;padding:12px;text-decoration:none;color:#596477;font-size:11px;font-weight:800}.footer{margin-top:38px;background:#172033;color:#aeb7c8;text-align:center;padding:28px;font-size:11px}@media(max-width:900px){.wrap{display:block}.side{position:static;max-height:none;margin-bottom:14px}.nav{display:none}.grid{grid-template-columns:1fr}.flow{grid-template-columns:repeat(3,1fr)}}@media(max-width:560px){.wrap{width:calc(100% - 20px)}.hero{padding:22px 18px}.card{padding:17px}.flow{grid-template-columns:1fr 1fr}.relatedgrid{grid-template-columns:1fr}.hero h1{font-size:34px}}
</style></head><body><header class="kb-header"><nav class="kb-nav"><a class="brand" href="/knowledge-base/"><span class="brandmark"><i class="fa-solid <?=$fa($icon)?>"></i></span><span>SmartToolz Knowledge</span></a><div class="nav"><a href="/knowledge-base/"><i class="fa-solid fa-house"></i> Knowledge Base</a><a href="/smart-toolz/tool.php"><i class="fa-solid fa-table-cells-large"></i> All Tools</a></div></nav></header><div class="wrap"><aside class="side"><h3><i class="fa-solid fa-book-open"></i> <?=$h($category)?> guides</h3><input class="search" id="guideSearch" placeholder="Search this category…"><div id="guideList"><?php foreach($tools as $t):if((string)$t['category']!==$category)continue;$p=trim((string)parse_url($t['url'],PHP_URL_PATH),'/');$s=basename($p,'.php');?><a class="tool <?=$s===$slug?'current':''?>" data-name="<?=$h(strtolower((string)$t['name']))?>" href="/knowledge-base/<?=rawurlencode($s)?>/article/"><i class="fa-solid <?=$fa((string)($t['icon']??''))?>"></i><?=$h((string)$t['name'])?></a><?php endforeach;?></div></aside><main class="main"><div class="crumb"><a href="/knowledge-base/"><i class="fa-solid fa-arrow-left"></i> Knowledge Base</a> / <?=$h($category)?> / <?=$h($name)?></div><section class="hero"><div class="eyebrow"><i class="fa-solid <?=$fa($icon)?>"></i> <?=$h($category)?></div><h1>How to Use <?=$h($name)?></h1><p><?=$h($description)?> <?=$h($guide['purpose'])?></p><a class="open" href="<?=$h($url)?>"><i class="fa-solid fa-arrow-up-right-from-square"></i> Open <?=$h($name)?></a></section><div class="flow"><?php foreach($flow as $ico=>$label):?><div class="flowbox"><i class="fa-solid <?=$ico?>"></i><b><?=$label?></b><span><?=['Input'=>'Give it the right input','Configure'=>'Choose the required option','Run'=>'Start the main action','Review'=>'Check the actual result','Output'=>'Copy, download or use it'][$label]?></span></div><?php endforeach;?></div><div class="grid"><section class="card"><h2><i class="fa-solid fa-circle-info"></i> What this tool actually does</h2><p><?=$h($guide['purpose'])?></p></section><section class="card"><h2><i class="fa-solid fa-box-open"></i> What you need</h2><div class="input"><?=$h($guide['input'])?></div></section></div><section class="card steps"><h2><i class="fa-solid fa-list-check"></i> Exact workflow</h2><?php foreach($guide['steps'] as $i=>$step):?><div class="step"><span class="num"><?=$i+1?></span><div><h3>Step <?=$i+1?></h3><p><?=$h($step)?></p></div></div><?php endforeach;?></section><section class="card tips"><h2><i class="fa-solid fa-lightbulb"></i> Tips for better results</h2><ul><?php foreach($guide['tips'] as $tip):?><li><?=$h($tip)?></li><?php endforeach;?></ul></section><section class="card mistakes"><h2><i class="fa-solid fa-triangle-exclamation"></i> Common mistakes</h2><?php foreach($guide['mistakes'] as $mistake):?><div class="row"><i class="fa-solid fa-xmark"></i> <?=$h($mistake)?></div><?php endforeach;?></section><section class="card result"><h2><i class="fa-solid fa-circle-check"></i> What you should get</h2><p><?=$h($guide['output'])?></p></section><section class="card"><h2><i class="fa-solid fa-circle-question"></i> Quick answers</h2><p><strong>Do I need to install anything?</strong><br>Normally no. Open the tool in a modern browser.</p><p><strong>What if the result looks wrong?</strong><br>Return to the input and option checks above, correct the values/file/settings, then run the tool again.</p><p><strong>Should I keep the original?</strong><br>Yes. Keep the source until you have verified the finished result.</p></section><?php if($related):?><section class="card"><h2><i class="fa-solid fa-layer-group"></i> Related <?=$h($category)?> tools</h2><div class="relatedgrid"><?php foreach(array_slice($related,0,9) as $t):$p=trim((string)parse_url($t['url'],PHP_URL_PATH),'/');$s=basename($p,'.php');?><a href="/knowledge-base/<?=rawurlencode($s)?>/article/"><i class="fa-solid <?=$fa((string)($t['icon']??''))?>"></i><?=$h((string)$t['name'])?></a><?php endforeach;?></div></section><?php endif;?><footer class="footer">SmartToolz Knowledge Base · Tool-specific practical guides</footer></main></div><script>const q=document.getElementById('guideSearch');q?.addEventListener('input',()=>{const v=q.value.toLowerCase().trim();document.querySelectorAll('#guideList .tool').forEach(a=>a.hidden=v!==''&&!a.dataset.name.includes(v));});</script></body></html>
